package main

import "fmt"

// Number admits any type whose underlying type is int or float64,
// INCLUDING named types thanks to the tilde.
type Number interface {
	~int | ~float64
}

// Sum works for any Number; + is valid for all members of the set.
func Sum[T Number](xs []T) T {
	var total T // zero value of T
	for _, x := range xs {
		total += x
	}
	return total
}

type Celsius int // underlying type int -> matches ~int

func main() {
	fmt.Println(Sum([]int{1, 2, 3}))               // inference: T=int
	fmt.Println(Sum([]float64{1.5, 2.5}))          // T=float64
	fmt.Println(Sum([]Celsius{10, 20, 30}))        // named type, allowed by ~int
}

