package main

import "fmt"

// Map transforms a []T into a []U by applying f to each element.
// `any` is the loosest constraint — we only move values around, no operations.
func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s)) // pre-sized result
	for i, v := range s {
		out[i] = f(v)        // apply the transform
	}
	return out
}

func main() {
	words := []string{"go", "rocks"}
	// Type inference deduces T=string, U=int from the arguments.
	lengths := Map(words, func(w string) int { return len(w) })
	fmt.Println(lengths) // [2 5]
}

