package solution

// Filter returns the elements of s for which keep(elem) is true, in order.
// `any` is correct: we never inspect T, only move values and call keep.
func Filter[T any](s []T, keep func(T) bool) []T {
	out := make([]T, 0, len(s)) // pre-size to avoid growth copies
	for _, v := range s {
		if keep(v) {            // include only matching elements
			out = append(out, v)
		}
	}
	return out
}

