package solution

import (
	"reflect"
	"testing"
)

func TestFilter(t *testing.T) {
	even := func(n int) bool { return n%2 == 0 }
	gotI := Filter([]int{1, 2, 3, 4}, even)
	if !reflect.DeepEqual(gotI, []int{2, 4}) {
		t.Errorf("ints: got %v want [2 4]", gotI)
	}
	nonEmpty := func(s string) bool { return s != "" }
	gotS := Filter([]string{"a", "", "b"}, nonEmpty)
	if !reflect.DeepEqual(gotS, []string{"a", "b"}) {
		t.Errorf("strings: got %v want [a b]", gotS)
	}
}

